"""Check synchronization/evidence freshness; this is not a product safety pass."""

import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


def digest(path):
    return hashlib.sha256((ROOT / path).read_bytes()).hexdigest()


def main():
    failures = []
    checked = {}
    try:
        coverage = json.loads((ROOT / "verification/coverage.json").read_text())
        for path, expected in coverage["synchronization"]["files"].items():
            actual = digest(path)
            checked[path] = actual
            if actual != expected:
                failures.append("Content changed: " + path)
        snapshot = ROOT / coverage["synchronization"]["source_copy"]
        if snapshot.read_bytes() != (ROOT / "lease.py").read_bytes():
            failures.append("Synchronization snapshot differs from actual lease.py")
        current = json.loads((ROOT / "verification/evidence/current.json").read_text())
        if (not current["completed"] or current["correspondence"]["holds"] is not True
                or current["correspondence"]["schedules_checked"] != 256):
            failures.append("Incomplete or mismatched correspondence evidence")
        for side in ("implementation", "model"):
            summary = current[side]
            if (summary["schedules_checked"] != 256
                    or summary["observations_checked"] != 2048):
                failures.append("Incomplete scheduling evidence: " + side)
        expected_result = coverage["result"]
        if (current["status"] != expected_result["status"]
                or current["implementation"]["holds"] != expected_result["holds"]
                or current["implementation"]["unsafe_schedules"] != expected_result["unsafe_schedules"]):
            failures.append("Recorded safety result differs from actual evidence")
        evidence_hashes = {
            "lease.py": current["inputs"]["implementation"]["sha256"],
            "SPEC.md": current["inputs"]["contract_sha256"],
            "verification/model.py": current["inputs"]["model"]["sha256"],
            "verification/check_lease.py": current["inputs"]["checker_sha256"],
        }
        for path, expected in evidence_hashes.items():
            if digest(path) != expected:
                failures.append("Evidence describes different content: " + path)
        rehearsal = json.loads((ROOT / "verification/evidence/rehearsal.json").read_text())
        if (not rehearsal["completed"] or not rehearsal["baseline_restored"]
                or not rehearsal["temporary_resources_removed"]):
            failures.append("Rehearsal did not complete and restore resources")
        if rehearsal["cases"]["current_after"]["result"] != current:
            failures.append("Rehearsal used different current baseline")
        for path in ("lease.py", "SPEC.md"):
            baseline = json.loads((ROOT / "verification/evidence/baseline.json").read_text())
            if digest(path) != baseline["input_sha256"][path]:
                failures.append("Protected file changed during maintenance: " + path)
    except Exception as error:
        failures.append(type(error).__name__ + ": " + str(error))
    report = {"fresh": not failures, "failures": failures, "checked_sha256": checked,
              "meaning": "Record freshness only; inspect current.json for safety result"}
    output = ROOT / "verification/evidence/record-check.json"
    output.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n")
    print(json.dumps(report, sort_keys=True))
    return 0 if not failures else 1


if __name__ == "__main__":
    raise SystemExit(main())

